82	/** `per × count` — the scaled HP a count-scaling clause contributes, tallying its
83	    resource off the board as of attack declaration (§8.5 — counted when damage is
84	    calculated). Fold-agnostic: the caller adds this onto the printed base (the
85	    additive "+" family) or uses it as the whole damage (the "×"/multiply family).
86	    `attacker` is the attacking Active; `state` + `defenderSeat` reach the
87	    opponent's board for the Prize-count source (Charizard ex "Burning Darkness",
88	    Pecharunt ex "Irritated Outburst"). */
89	function scaledAttackDamage(
90	  attacker: InPlayPokemon,
91	  bonus: AttackDamageBonus,
92	  state: GameState,
93	  defenderSeat: Seat,
94	): number {
95	  switch (bonus.count.kind) {
96	    case "damageCountersOnSelf":
97	      // One damage counter = 10 HP (§12); floor for safety though all damage
98	      // lands in tens.
99	      return Math.floor(attacker.damage / 10) * bonus.per;
100	    case "opponentPrizesTaken":
101	      // Prizes the opponent has TAKEN (6 − their remaining pile, §8.1), read at
102	      // declaration before this attack's own KOs award any Prize.
103	      return takenPrizes(state, defenderSeat) * bonus.per;
104	  }
105	}
