107	/** §8 — declare one attack with the Active Pokémon; resolving it ends the
108	    turn through the staged tail. The cost is a CHECK, not a payment (§8.2):
109	    energy stays attached unless attack text discards it (M4). */
110	export function attack(state: GameState, action: AttackAction): ApplyResult {
111	  const rejected = turnGate(state, action);
112	  if (rejected !== null) return rejected;
113	  // §4 — the going-first player may not attack on their first turn. Turn 1
114	  // is by construction the first player's turn (and the gate already proved
115	  // the actor owns the current turn), so the turn counter IS the check; the
116	  // second player's first turn is turn 2 and is unrestricted.
117	  if (state.turn === 1) {
118	    return err("FIRST_TURN_ATTACK", "the going-first player cannot attack on turn 1 (§4)");
119	  }
120	  const side = state.players[action.seat];
121	  const active = side.active;
122	  if (active === null) {
123	    // Unreachable — promotion is forced before the next action.
124	    return err("NO_TARGET", "no Active Pokémon to attack with");
125	  }
126	  // §8 step 1 / §12 — an Asleep or Paralyzed Active cannot attack at all.
127	  // (Confusion does NOT block declaring — it flips at resolution, below.)
128	  const rotation = active.conditions.rotation;
129	  if (isImmobilized(active.conditions)) {
130	    return err(
131	      "STATUS_PREVENTS_ATTACK",
132	      `${rotation === "asleep" ? "an Asleep" : "a Paralyzed"} Pokémon cannot attack (§12)`,
133	    );
134	  }
135	  const attackerUid = topUid(active);
136	  const attacker = topCardOf(state, active);
137	  if (attackerUid === undefined || attacker === undefined) {
138	    return err("UNKNOWN_CARD", "no catalog card for the Active Pokémon");
139	  }
140	  const attacks = attacksOf(attacker);
141	  const index = action.index;
142	  // Wire check (types are not validation): the integer gate matters because
143	  // a string "0" WOULD resolve `attacks["0"]` while corrupting everything
144	  // downstream that does arithmetic with it; the indexed access then covers
145	  // range (and noUncheckedIndexedAccess types it `| undefined` anyway).
146	  const declared = Number.isInteger(index) ? attacks[index] : undefined;
147	  if (declared === undefined) {
148	    return err("BAD_ATTACK_INDEX", `${attacker.name} has no attack at index ${String(index)}`);
149	  }
150	  // §8.2 cost check against what the attached energies provide (basic types,
151	  // special-energy units incl. wildcards — continuous.ts providedEnergy),
152	  // under the in-play Stadium's continuous cost effects (League HQ's Basic
153	  // surcharge).
154	  const provided = providedEnergy(state, active);
155	  const cost = effectiveAttackCost(state, active, declared.cost ?? []);
156	  if (!costMet(cost, provided)) {
157	    return err("ATTACK_COST_UNMET", `${declared.name} costs [${cost.join(", ")}]`);
158	  }
159	
160	  const defenderSeat = otherSeat(action.seat);
161	  const defenderSpot = activeTop(state, defenderSeat);
162	  if (defenderSpot === null) {
163	    // Unreachable — the KO'd side promotes (or loses) before play resumes.
164	    return err("NO_TARGET", "no Defending Pokémon");
165	  }
166	  const { active: defender, uid: defenderUid, card: defenderCard } = defenderSpot;
167	
168	  const events: GameEvent[] = [
169	    { type: "ATTACK_DECLARED", seat: action.seat, uid: attackerUid, attack: declared.name, index },
170	  ];
171	  let next = state;
172	
173	  // §8 step 3 — the confusion flip, AFTER every gate and the cost check
174	  // passed (§12): tails and the declared attack does not resolve at all —
175	  // no damage, no effects — the attacker takes 30 itself (possibly a
176	  // self-KO, prized to the defender) and the turn still ends.
177	  if (rotation === "confused") {
178	    const [face, rngState] = flipCoin(next.rngState);
179	    next = { ...next, rngState };
180	    events.push({ type: "CONFUSION_CHECK", seat: action.seat, uid: attackerUid, result: face });
181	    if (face === "tails") {
182	      events.push({
183	        type: "ATTACK_FAILED",
184	        seat: action.seat,
185	        uid: attackerUid,
186	        reason: "confusion",
187	      });
188	      const hurt = { ...active, damage: active.damage + 30 };
189	      next = withActive(next, action.seat, hurt);
190	      events.push({
191	        type: "COUNTERS_PLACED",
192	        seat: action.seat,
193	        uid: attackerUid,
194	        amount: 30,
195	        source: "confusion",
196	      });
197	      // The self-hit can KO the attacker itself — prized to the DEFENDER
198	      // (collectKnockOuts owes each KO's prize to the KO'd side's opponent). The
199	      // epilogue sweeps both boards; the defender took no damage on this failed
200	      // attack, so only the attacker's own board can be lethal here.
201	      return finishAttack(next, events, action.seat);
202	    }
203	  }
204	
205	  // Coverage strategy (simulator.md): the mechanical part of the attack
206	  // (numeric damage, weakness/resistance) is simulated, and effect text
207	  // derives into executable steps for exactly the sentence shapes effects.ts
208	  // recognizes — anything else (and every damage marker like "60+", M4's
209	  // effect ops) is flagged loudly instead of guessed.
210	  const { base, modifier } = parseAttackDamage(declared.damage);
211	  const effect = declared.effect ?? null;
212	  // Registry ABOVE the deriver (D8): an authored attack program wins; else the
213	  // text deriver; else null (unsimulated). None of the representative attacks
214	  // are registry-authored, so this reads through to the deriver today — the
215	  // seam is here for when they are.
216	  const authored = programFor(attacker.id)?.attack ?? null;
217	  const derived = effect === null || effect === "" ? null : deriveAttackEffect(effect);
218	  const program = authored ?? derived;
219	  // The count-scaling clause reads the SAME effect text but folds into the damage
220	  // BEFORE the §8.5 pipeline, unlike a post-damage program. Two sibling families,
221	  // told apart by the word "more": ADDITIVE ("+") folds `per × count` onto the
222	  // printed base; MULTIPLY ("×", no "more") makes `per × count` the WHOLE damage,
223	  // the printed base dropped. Their regexes are mutually exclusive, so at most one
224	  // fires — read multiply only when additive did not, making that explicit. A card
225	  // carries at most one scaling clause OR a program: the whole-sentence anchor
226	  // means a scaling sentence never also derives an op.
227	  const damageBonus = effect === null || effect === "" ? null : deriveAttackDamageBonus(effect);
