2661	function interchangeableCandidates(
2662	  state: GameState,
2663	  discardable: readonly { uid: string; from: PokemonRef }[],
2664	  cap: number,
2665	): { uid: string; from: PokemonRef }[] {
2666	  const kept = new Map<string, number>();
2667	  const out: { uid: string; from: PokemonRef }[] = [];
2668	  for (const candidate of discardable) {
2669	    const key = `${refKeyOf(candidate.from)}|${cardIdentity(state, candidate.uid)}`;
2670	    const already = kept.get(key) ?? 0;
2671	    if (already >= cap) continue;
2672	    kept.set(key, already + 1);
2673	    out.push(candidate);
2674	  }
2675	  return out;
2676	}
2677	
2678	/** The picks a discardEnergy makes with NO choice left in it (the M1 doctrine),
2679	    or null when the player must decide. Runs over the COLLAPSED candidate set
2680	    above, so "as many candidates as the count" already means "as many
2681	    DISTINGUISHABLE ones".
2682	    "total": the offer holds no more than the count — every candidate comes off,
2683	    which covers both the exact fit (one candidate for "an Energy"; three for
2684	    Koraidon's "Discard 3") and the SHORT board, where "do as much as you can"
2685	    takes everything there is and asks nothing.
2686	    "each": every affected Pokémon has exactly one — the common Giacomo board,
2687	    where "one Special Energy off each" names itself. */
2688	function forcedDiscards(
2689	  discardable: readonly { uid: string; from: PokemonRef }[],
2690	  scope: DiscardScope,
2691	): string[] | null {
2692	  if (scope.kind === "total") {
2693	    return discardable.length <= scope.count ? discardable.map((d) => d.uid) : null;
2694	  }
2695	  const perSource = new Map<string, string[]>();
2696	  for (const { uid, from } of discardable) {
2697	    const key = refKeyOf(from);
2698	    const bucket = perSource.get(key);
2699	    if (bucket === undefined) perSource.set(key, [uid]);
2700	    else bucket.push(uid);
2701	  }
2702	  const picks: string[] = [];
2703	  for (const bucket of perSource.values()) {
2704	    const only = bucket[0];
2705	    if (bucket.length !== 1 || only === undefined) return null; // a real choice
2706	    picks.push(only);
2707	  }
2708	  return picks;
2709	}
2710	
2711	/** A stable key for grouping/comparing refs inside the interpreter (cardplay.ts
2712	    has its own copy for wire validation — the two never share a value). */
2713	function refKeyOf(ref: PokemonRef): string {
2714	  return `${ref.seat}:${ref.spot.spot}:${ref.spot.spot === "bench" ? ref.spot.index : "active"}`;
2715	}
2716	
2717	/** A moveEnergy op does something iff the controller has ≥1 Energy the filter
2718	    admits AND ≥2 of their own Pokémon in play (a source WITH a distinct
2719	    destination). Exported for programPlayable: a play that could only whiff can't
2720	    be made (the gust / attachEnergyFrom precedent). */
2721	export function moveEnergyPlayable(
2722	  state: GameState,
2723	  seat: Seat,
2724	  op: Extract<EffectOp, { op: "moveEnergy" }>,
2725	): boolean {
2726	  const { movable, destinations, needed } = moveEndpoints(state, seat, op);
2727	  return op.max > 0 && movable.length > 0 && destinations.length >= needed;
2728	}
2729	
2730	/** What a `moveEnergy` op can take, where it can put it, and how many
2731	    destinations that route needs to be worth asking about — ONE rule with two
2732	    readers (the op's own no-op test and the `programPlayable` gate above), for
2733	    the same reason the filter reads provision through one helper: the play gate
2734	    and the play itself disagreeing is how a card becomes playable and then does
2735	    nothing, or is refused while a legal move existed.
2736	
2737	    The free route (Energy Switch / Poppy) takes from anywhere and needs TWO
