const FIX_GATEDSUP: CardProgram = {
  trainerPlayableIf: { kind: "morePrizesThanOpponent" },
  trainer: [{ op: "drawCards", count: 1 }],
};

// ── M5 op-slice: discardEnergy (the §15 energy-removal "hammer" family) —
