19	// M5 op-slice: ATTACK EFFECT PROGRAMS CAN PARK — the `attackEpilogue` stage.
20	//
21	// attack.ts used to run an attack's effect program as `runProgram(...).state`,
22	// which silently DROPPED a parked prompt and every op behind it. It now seeds a
23	// one-stage `pending` queue before the program runs and folds through
24	// settleProgram's `resumeTail`, so a program that stops for a decision leaves the
25	// epilogue (the §8.1 KO sweep + the §5.3 turn end) waiting in the queue, and
26	// resolveEffect drains it once the answer lands.
27	//
28	// The card family that needs it is the self-discard attack COST, a DERIVED effect
29	// (there is no registry row — effects.ts reads the printed sentence):
30	//   • "Discard an Energy from this Pokémon."  → discardEnergy yourActive (PARKS
31	//     when the attacker holds two distinguishable Energy);
32	//   • "Discard all Energy from this Pokémon." → the same op with count "all",
33	//     which asks nothing and resolves inline.
34	
35	function find<T extends GameEvent["type"]>(
36	  events: GameEvent[],
37	  type: T,
38	): Extract<GameEvent, { type: T }> | undefined {
39	  return events.find((e) => e.type === type) as Extract<GameEvent, { type: T }> | undefined;
40	}
41	
42	/** Setup, then open P1's turn 2 (P2 went first and passed) — P1's first
43	    unrestricted turn, so attacking is legal (§4). */
44	function board(seed: number): GameState {
45	  const state = driveSetup(seed, { p1: ATTACK_PARK_DECK, p2: ATTACK_PARK_DECK }, { first: "p2" });
46	  return mustApply(state, { type: "endTurn", seat: "p2" }).state;
47	}
48	
49	function activeEnergy(state: GameState, seat: "p1" | "p2"): string[] {
50	  return [...(state.players[seat].active?.energy ?? [])];
51	}
52	
53	/** P1 fields `attackerId` with `energy` attached and P2 fields `defenderId`. */
54	function matchup(
55	  seed: number,
56	  attackerId: string,
57	  defenderId: string,
58	  energy: readonly { id: string; count: number }[],
59	): GameState {
60	  let state = setActiveFromDeck(board(seed), "p1", attackerId);
61	  state = setActiveFromDeck(state, "p2", defenderId);
62	  for (const { id, count } of energy) state = attachFromDeck(state, "p1", id, count);
63	  return state;
64	}
