39	function find<T extends GameEvent["type"]>(
40	  events: GameEvent[],
41	  type: T,
42	): Extract<GameEvent, { type: T }> | undefined {
43	  return events.find((e) => e.type === type) as Extract<GameEvent, { type: T }> | undefined;
44	}
45	
46	/** Setup with BOTH Actives pinned to fix-lightning-weak (×2 Lightning, 130 HP, empty
47	    Bench — a deterministic Defender that is the W/R target), then open P1's turn 2. */
48	function board(seed: number, deck: string[] = ANY_SNIPE_DECK): GameState {
49	  const state = driveSetup(
50	    seed,
51	    { p1: deck, p2: deck },
52	    { first: "p2", active: { p1: "fix-lightning-weak", p2: "fix-lightning-weak" } },
53	  );
54	  return mustApply(state, { type: "endTurn", seat: "p2" }).state;
55	}
56	
57	/** P1 fields `attacker` with `energy` attached; P2 keeps its fix-lightning-weak
58	    Active and its Bench holds exactly `benched`. */
59	function anySnipe(
60	  seed: number,
61	  opts: { attacker: string; energy: number; benched: readonly string[] },
62	  deck: string[] = ANY_SNIPE_DECK,
63	): GameState {
64	  let state = setActiveFromDeck(board(seed, deck), "p1", opts.attacker);
65	  state = attachFromDeck(state, "p1", "fix-lightning-energy", opts.energy);
66	  for (const body of opts.benched) state = benchFromDeck(state, "p2", body);
67	  return state;
68	}
