20	// M5 op-slice: the `providesEnergy` CardFilter — "an Energy that PROVIDES {X}".
21	//
22	// The last missing piece of the energy-discard family, and the first filter a
23	// CARD alone cannot answer. Two claims carry the whole slice:
24	//
25	//   1. PROVISION, NOT PRINT. "{L} Energy" is not "a Basic Lightning Energy card".
26	//      A Special Energy that provides {L} IS one; a Special that provides only
27	//      {C} is not. The predicate therefore reads the same units §8.2's cost
28	//      matcher reads (continuous.ts) — pay a {L} cost with a card and the very
29	//      same attack must be able to discard it.
30	//   2. HOST, NOT CARD. Provision is a while-ATTACHED property, and for Luminous
31	//      Energy it depends on the holder's OTHER attachments. The identical card is
32	//      a {L} Energy alone and NOT one beside another Special Energy, so the
33	//      filter is answered per Energy on its host (`matchesAttached`) and the
34	//      card-only pile scanner (`matchesFilter`) answers false for it.
35	//
36	// TWO consumers, one vocabulary (the D40 shape): the DERIVED typed self-discard
37	// (Kilowattrel, Arcanine ex, Charmeleon, Charizard — no registry rows) and
38	// `moveEnergy`'s new benchToActive route (Armarouge's "Fire Off").
39	
40	/** Setup, then open P1's turn 2 (P2 went first and passed) — P1's first
41	    unrestricted turn, so attacking and Abilities are both legal (§4). */
42	function board(seed: number): GameState {
43	  const state = driveSetup(
44	    seed,
45	    { p1: PROVIDES_ENERGY_DECK, p2: PROVIDES_ENERGY_DECK },
46	    { first: "p2" },
47	  );
48	  return mustApply(state, { type: "endTurn", seat: "p2" }).state;
49	}
50	
51	function activeEnergy(state: GameState, seat: "p1" | "p2"): string[] {
52	  return [...(state.players[seat].active?.energy ?? [])];
53	}
54	
55	function benchEnergy(state: GameState, seat: "p1" | "p2", index: number): string[] {
56	  return [...(state.players[seat].bench[index]?.energy ?? [])];
57	}
58	
59	/** P1 fields `attackerId` with `attached` Energy, against a defender that
60	    survives everything printed in this deck (so no KO tail interferes). */
61	function fielded(
62	  seed: number,
63	  attackerId: string,
64	  attached: readonly { id: string; count: number }[],
65	): GameState {
66	  let state = board(seed);
67	  state = setActiveFromDeck(state, "p1", attackerId);
68	  state = setActiveFromDeck(state, "p2", "fix-titan");
69	  for (const { id, count } of attached) state = attachFromDeck(state, "p1", id, count);
70	  return state;
71	}
72	
73	/** The card ids of the Energy the parked discard prompt is offering. */
74	function offered(state: GameState): string[] {
75	  if (state.phase.kind !== "effect:choose") throw new Error("expected effect:choose");
76	  if (state.phase.prompt.kind !== "discardEnergy") throw new Error("expected discardEnergy");
77	  return state.phase.prompt.discardable.map((d) => state.cardIdByUid[d.uid] as string);
78	}
