18	// 0.34.0 → 0.36.0 — count-scaled attack damage: two sibling families, told apart
19	// by the word "more".
20	//
21	// ADDITIVE ("+", "… does N MORE damage for each …") folds N × count ONTO the
22	// printed base. SIMULATED for two count sources: the attacker's OWN damage
23	// counters (Paldean Tauros sv02-028 "Raging Horns", fix-attacker "Rage") and — the
24	// opponent's taken Prizes (Charizard ex sv03-125 "Burning Darkness"). MULTIPLY
25	// ("×", "… does N damage for each …", no "more") makes N × count the WHOLE damage,
26	// the printed "N×" base dropped — SIMULATED (0.36.0) for the Prize twins Pecharunt
27	// ex sv06.5-039 (60×) and Annihilape sv01-109 (70×). Both reuse ONE count evaluator
28	// (opponentPrizesTaken); deriveAttackDamageBonus / deriveAttackDamageMultiplier read
29	// the anchored sentence, and attack.ts folds N × count BEFORE the §8.5 W/R pipeline
30	// — a DAMAGE_DEALT `scaled` field, at the same pre-W/R step as the continuous
31	// Vitality Band bonus. The "+"/"×"/effect is no longer flagged loudly for these.
32	//
33	// Entei sv03-030 "Blaze Ball" ("… for each {R} Energy attached to this Pokémon.")
34	// is an additive "+" whose count source no reader simulates — it STAYS on the loud
35	// ATTACK_EFFECT_SKIPPED path, the anchor-guard witness (replacing Charizard) that
36	// the additive deriver is narrow; Wo-Chien ex (benched-target) and Chien-Pao ex
37	// (discarded-Energy count) are the multiply deriver's.
38	
39	function find<T extends GameEvent["type"]>(
40	  events: GameEvent[],
41	  type: T,
42	): Extract<GameEvent, { type: T }> | undefined {
43	  return events.find((e) => e.type === type) as Extract<GameEvent, { type: T }> | undefined;
44	}
