46	/** Setup then open P1's turn 2 (P2 went first and passed) — P1 goes second, so
47	    turn 2 is their first turn with no §4 attack restriction. */
48	function p1Turn2(seed: number): GameState {
49	  const state = driveSetup(seed, { p1: SCALED_DAMAGE_DECK, p2: SCALED_DAMAGE_DECK }, { first: "p2" });
50	  return must(applyAction(state, { type: "endTurn", seat: "p2" }));
51	}
