53	/** P1 fields `attacker` with `energy` Fire attached and `damage` HP already on it
54	    (its damage counters are what the scaling reads), P2 fields `defender`. The two
55	    scaling attackers are Basics and Charizard is a Stage 2, but setActiveFromDeck
56	    force-places either — the surgery reads the stack top, not the stage. */
57	function matchup(
58	  seed: number,
59	  opts: { attacker: string; defender: string; energy: number; damage?: number },
60	): GameState {
61	  let state = p1Turn2(seed);
62	  state = setActiveFromDeck(state, "p1", opts.attacker);
63	  state = attachFromDeck(state, "p1", "fix-fire-energy", opts.energy);
64	  if (opts.damage !== undefined) state = setDamage(state, "p1", opts.damage);
65	  return setActiveFromDeck(state, "p2", opts.defender);
66	}
