16	// M5 (prize value, §8.1) — prizeValueOf turned real: a KO is worth 3 Prizes for
17	// a VMAX, 2 for any other rule box (ex / V / VSTAR / GX), 1 for a plain body.
18	// The class is read off the printed name suffix (pokemonSuffixOf, unit-tested in
19	// cards.test.ts). This suite pins the KO→count wiring end to end: P1's fix-attacker
20	// Bites a pre-damaged P2 Active to lethal and we read the Prize count the KO owes.
21	
22	/** Setup then open P1's turn 2 (P2 went first and passed) — P1 goes second, so
23	    turn 2 is their first turn with no §4 attack restriction. */
24	function p1Turn2(seed: number): GameState {
25	  const state = driveSetup(seed, { p1: PRIZE_DECK, p2: PRIZE_DECK }, { first: "p2" });
26	  return must(applyAction(state, { type: "endTurn", seat: "p2" }));
27	}
28	
29	function find<T extends GameEvent["type"]>(
30	  events: GameEvent[],
31	  type: T,
32	): Extract<GameEvent, { type: T }> | undefined {
33	  return events.find((e) => e.type === type) as Extract<GameEvent, { type: T }> | undefined;
34	}
35	
36	/** P1 fix-attacker (energied for Bite [C] 30) vs a P2 Active of `activeId`,
37	    pre-damaged so the 30 is lethal. setActiveFromDeck displaces P2's setup Active
38	    to the bench, so the ensuing Active KO always has a Pokémon to promote into. */
39	function biteVs(seed: number, activeId: string, hp: number): GameState {
40	  let state = p1Turn2(seed);
41	  state = setActiveFromDeck(state, "p1", "fix-attacker");
42	  state = attachFromDeck(state, "p1", "fix-energy", 1); // pays Bite [C]
43	  state = setActiveFromDeck(state, "p2", activeId);
44	  return setDamage(state, "p2", hp - 30); // Bite's 30 finishes it
45	}
